INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10001, /*where_type*/2002, /*character_id*/126401, /*face_type*/2, /*character_name*/'克萝茜', /*description*/'欢迎光临♪\n可以用驾车游币\n购物哦！', /*voice_id*/1, /*start_time*/'2025/05/15 11:00:00', /*end_time*/'2025/07/07 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/1.47, /*change_face_type*/1, /*season_id*/1);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10002, /*where_type*/2002, /*character_id*/126401, /*face_type*/1, /*character_name*/'克萝茜', /*description*/'这里的商品种类繁多\n请尽情地\n挑选吧♪', /*voice_id*/2, /*start_time*/'2025/05/15 11:00:00', /*end_time*/'2025/07/07 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/2.15, /*change_face_type*/2, /*season_id*/1);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10003, /*where_type*/2002, /*character_id*/126501, /*face_type*/2, /*character_name*/'莱拉耶尔', /*description*/'欢迎光临来到商店\n驾车游币可以在这里\n兑换道具哦', /*voice_id*/1, /*start_time*/'2025/05/15 11:00:00', /*end_time*/'2025/07/07 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*season_id*/1);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10004, /*where_type*/2002, /*character_id*/126501, /*face_type*/1, /*character_name*/'莱拉耶尔', /*description*/'请在本商店\n购买道具\n享受美好的旅途吧', /*voice_id*/2, /*start_time*/'2025/05/15 11:00:00', /*end_time*/'2025/07/07 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*season_id*/1);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10005, /*where_type*/2002, /*character_id*/127702, /*face_type*/2, /*character_name*/'琳德', /*description*/'欢迎光临\n可以使用驾车游币\n进行购物哦', /*voice_id*/1, /*start_time*/'2025/06/30 11:00:00', /*end_time*/'2025/08/21 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*season_id*/2);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10006, /*where_type*/2002, /*character_id*/127702, /*face_type*/2, /*character_name*/'琳德', /*description*/'商店打扫得一尘不染\n毕竟是公主殿下\n直营商店呢', /*voice_id*/2, /*start_time*/'2025/06/30 11:00:00', /*end_time*/'2025/08/21 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*season_id*/2);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10007, /*where_type*/2002, /*character_id*/127802, /*face_type*/1, /*character_name*/'维尔姆', /*description*/'欢迎光临商店\n可以用驾车游币交换物品\n请随意看看', /*voice_id*/1, /*start_time*/'2025/06/30 11:00:00', /*end_time*/'2025/08/21 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*season_id*/2);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10008, /*where_type*/2002, /*character_id*/127802, /*face_type*/1, /*character_name*/'维尔姆', /*description*/'为什么要让我看店啊……\n不过我会好好做的\n尽管挑选喜欢的东西吧', /*voice_id*/2, /*start_time*/'2025/06/30 11:00:00', /*end_time*/'2025/08/21 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/6.5, /*change_face_type*/2, /*season_id*/2);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10009, /*where_type*/2002, /*character_id*/129602, /*face_type*/1, /*character_name*/'银莲', /*description*/'——欢迎光临\n如果有驾车游币的话\n可以在这里买东西哦', /*voice_id*/1, /*start_time*/'2025/08/14 11:00:00', /*end_time*/'2025/10/20 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*season_id*/3);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10010, /*where_type*/2002, /*character_id*/129602, /*face_type*/1, /*character_name*/'银莲', /*description*/'——想要我多笑一点？\n无论你有多少货币\n有些东西依然是买不到的哦', /*voice_id*/2, /*start_time*/'2025/08/14 11:00:00', /*end_time*/'2025/10/20 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*season_id*/3);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10011, /*where_type*/2002, /*character_id*/129701, /*face_type*/1, /*character_name*/'涅妃＝涅菈', /*description*/'欢迎光临\n请在这里用驾车游币\n交换道具', /*voice_id*/1, /*start_time*/'2025/08/14 11:00:00', /*end_time*/'2025/10/20 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*season_id*/3);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10012, /*where_type*/2002, /*character_id*/129701, /*face_type*/1, /*character_name*/'涅妃＝涅菈', /*description*/'顺便问一下，花多少钱\n才能挽回你呢？\n——呵呵，我开玩笑的', /*voice_id*/2, /*start_time*/'2025/08/14 11:00:00', /*end_time*/'2025/10/20 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/6.2, /*change_face_type*/2, /*season_id*/3);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10013, /*where_type*/2002, /*character_id*/130301, /*face_type*/5, /*character_name*/'花音', /*description*/'欢、欢迎光临！\n哼……居然让本小姐来看店……\n真是屈辱', /*voice_id*/1, /*start_time*/'2025/10/13 11:00:00', /*end_time*/'2025/12/06 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/3.1, /*change_face_type*/3, /*season_id*/4);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10014, /*where_type*/2002, /*character_id*/130301, /*face_type*/2, /*character_name*/'花音', /*description*/'哎呀，竟然看上了我？\n真不巧，这点小钱……\n居然买得起！？', /*voice_id*/2, /*start_time*/'2025/10/13 11:00:00', /*end_time*/'2025/12/06 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/6.15, /*change_face_type*/3, /*season_id*/4);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10015, /*where_type*/2002, /*character_id*/130401, /*face_type*/2, /*character_name*/'纳娜', /*description*/'欢迎光临♪\n好像可以用“驾车游币”？\n来兑换道具哦～', /*voice_id*/1, /*start_time*/'2025/10/13 11:00:00', /*end_time*/'2025/12/06 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*season_id*/4);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10016, /*where_type*/2002, /*character_id*/130401, /*face_type*/1, /*character_name*/'纳娜', /*description*/'给我甜点的话 \n就把纳娜捡来的\n松果当谢礼！', /*voice_id*/2, /*start_time*/'2025/10/13 11:00:00', /*end_time*/'2025/12/06 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/3.35, /*change_face_type*/2, /*season_id*/4);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10017, /*where_type*/2002, /*character_id*/130502, /*face_type*/1, /*character_name*/'凤凰', /*description*/'欢迎光临商店\n凤凰会为大家\n献上祝福', /*voice_id*/1, /*start_time*/'2025/11/29 11:00:00', /*end_time*/'2026/02/05 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*season_id*/5);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10018, /*where_type*/2002, /*character_id*/130502, /*face_type*/1, /*character_name*/'凤凰', /*description*/'这里可不卖\n称呼我“小凤”的权利哦？\n这是给骑士先生的特权！', /*voice_id*/2, /*start_time*/'2025/11/29 11:00:00', /*end_time*/'2026/02/05 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/3.18, /*change_face_type*/2, /*season_id*/5);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10019, /*where_type*/2002, /*character_id*/130503, /*face_type*/4, /*character_name*/'凤凰', /*description*/'呜啊啊啊啊！\n怎么又穿成这个样子了！\n请捐点钱吧！', /*voice_id*/3, /*start_time*/'2025/11/29 11:00:00', /*end_time*/'2026/02/05 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/4, /*season_id*/5);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10020, /*where_type*/2002, /*character_id*/123301, /*face_type*/2, /*character_name*/'涅亚', /*description*/'你好♪\n想兑换什么都可以～\n卡利萨弟弟除外。', /*voice_id*/1, /*start_time*/'2025/11/29 11:00:00', /*end_time*/'2026/02/05 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/4.9, /*change_face_type*/1, /*season_id*/5);
INSERT INTO `caravan_navi_comment` VALUES (/*comment_id*/10021, /*where_type*/2002, /*character_id*/123301, /*face_type*/2, /*character_name*/'涅亚', /*description*/'对了，买下骑士弟弟\n需要几万金币呢？\n不是开、玩、笑哦♡', /*voice_id*/2, /*start_time*/'2025/11/29 11:00:00', /*end_time*/'2026/02/05 10:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/4.8, /*change_face_type*/1, /*season_id*/5);
